'use strict';
// Auto-generated from backend/templates PNGs. Do not edit by hand.
// Embedded so Vercel serverless bundles include the template images.

const fs = require('fs').promises;
const path = require('path');

const decodedCache = new Map();

const EMBEDDED = {
  "cmps-form-template.png": "",
  "cmps-form-template-landscape.png": "",
};

async function loadTemplateImageBytes(fileName) {
  // The embedded PNGs decode from ~2MB of base64 — cache the decoded bytes
  // per process so repeat renders don't pay the decode cost every time.
  const cached = decodedCache.get(fileName);
  if (cached) return cached;
  try {
    const bytes = await fs.readFile(path.resolve(__dirname, '../templates', fileName));
    decodedCache.set(fileName, bytes);
    return bytes;
  } catch (err) {
    const b64 = EMBEDDED[fileName];
    if (!b64) throw err;
    const bytes = Buffer.from(b64, 'base64');
    decodedCache.set(fileName, bytes);
    return bytes;
  }
}

module.exports = { loadTemplateImageBytes };
